// Второй выпуск (+10 на тему): неравенства, текстовые задачи, прогрессии,
// функции. Уровень ЕНТ (B–C), русский и казахский текст рядом.
import type { Template } from '../helpers'
import { c, N, T, pick, rnd, fx, frac, type B } from './bi'
import { piFrac, poly } from '../more/common'

const Q = (ru: string, kk: string): B => [ru, kk]
const sg = (k: number) => (k < 0 ? `- ${-k}` : `+ ${k}`)
const xm = (a: number) => (a === 0 ? 'x' : `x ${sg(-a)}`) // x - a
const iv = (a: string | number, b: string | number, l = '(', r = ')') => `$${l}${a};\\ ${b}${r}$`
const INF = '+\\infty', NINF = '-\\infty'
const F = (p: number, q: number) => `$${frac(p, q)}$`
const pr = (k: number) => (k < 0 ? `(${fx(k)})` : fx(k))
const sumInt = (a: number, b: number) => ((a + b) * (b - a + 1)) / 2
const two = (lo = -6, hi = 8): [number, number] => { let p = 0, r = 0; while (p >= r) { p = rnd(lo, hi); r = rnd(lo, hi) } return [p, r] }
const ineq = (e: string): B => [`Решите неравенство $${e}$.`, `$${e}$ теңсіздігін шешіңіз.`]
const cntI = (e: string): B => [`Сколько целых решений имеет неравенство $${e}$?`, `$${e}$ теңсіздігінің неше бүтін шешімі бар?`]
const sumI = (e: string): B => [`Найдите сумму целых решений неравенства $${e}$.`, `$${e}$ теңсіздігінің бүтін шешімдерінің қосындысын табыңыз.`]
const sys = (a: string, b: string) => `\\begin{cases} ${a}, \\\\ ${b} \\end{cases}`
const sysQ = (s: string): B => [`Решите систему неравенств $${s}$.`, `$${s}$ теңсіздіктер жүйесін шешіңіз.`]
const sysC = (s: string): B => [`Сколько целых решений имеет система $${s}$?`, `$${s}$ жүйесінің неше бүтін шешімі бар?`]
const dom = (f: string): B => [`Найдите область определения функции $y = ${f}$.`, `$y = ${f}$ функциясының анықталу облысын табыңыз.`]
const rng = (f: string): B => [`Найдите множество значений функции $y = ${f}$.`, `$y = ${f}$ функциясының мәндер жиынын табыңыз.`]
const lim = (e: string): B => [`Вычислите $${e}$.`, `$${e}$ есептеңіз.`]

const I1 = 'Числовые промежутки: объединение и пересечение', I2 = 'Линейные неравенства', I3 = 'Квадратные неравенства'
const I4 = 'Рациональные неравенства. Метод интервалов', I5 = 'Иррациональные неравенства', I6 = 'Системы неравенств'
const W1 = 'Задачи на проценты', W2 = 'Задачи на смеси и сплавы', W3 = 'Задачи на совместную работу', W4 = 'Задачи на движение'
const W5 = 'Статистика: среднее, мода, медиана', W6 = 'Теория вероятностей'
const P1 = 'Арифметическая прогрессия', P2 = 'Геометрическая прогрессия', P3 = 'Бесконечно убывающая геометрическая прогрессия'
const F1 = 'Область определения функции', F2 = 'Множество значений функции', F3 = 'Нули функции. Пересечение с осями'
const F4 = 'Квадратичная функция', F5 = 'Чётность и периодичность', F6 = 'Обратная и сложная функция', F7 = 'Пределы и асимптоты'

